/**
 * Keeping the live preview's images current, as pure functions (no `vscode`
 * import, so they are unit-testable). instantPreview.ts wires them up.
 *
 * The preview links every image (author-supplied ones under `external/`,
 * `pretext generate` output under `generated/`) to the file on disk through a
 * webview URI. A page never fetches an image again while its URL stays the
 * same: the webview reuses the copy it already decoded, and a live patch
 * leaves an unchanged `<img>` alone. So when a file changes behind an
 * unchanged URL (a latex-image regenerated by a background `pretext build`,
 * a photo replaced in the external directory), the preview keeps showing the
 * old picture. Two things fix that:
 *
 * - every asset URL carries a version made from the file's modification time
 *   and size ({@link assetVersion}), so a changed file gets a new URL;
 * - the asset directories are watched, and a change in them re-delivers the
 *   page, so the new URL reaches the panel without waiting for the next edit
 *   ({@link watchedAssetDirs}, {@link assetWatchGlob}, {@link isInsideAny}).
 */

import * as path from "path";

/** The directories behind a page's `external/` and `generated/` URLs. */
export interface PreviewAssetDirs {
  external?: string;
  generated: string;
}

/**
 * A version string for an asset file, for the query of its webview URI. It
 * changes whenever the file is rewritten, which is all a cache-buster needs.
 * Size is included for a rewrite landing within the same millisecond.
 * Only unreserved characters, so the URI keeps it unencoded.
 */
export function assetVersion(stat: { mtimeMs: number; size: number }): string {
  return `${Math.trunc(stat.mtimeMs)}-${stat.size}`;
}

/** True when `file` is `dir` itself or lies somewhere below it. */
export function isInside(file: string, dir: string): boolean {
  const relative = path.relative(dir, file);
  return (
    relative === "" ||
    (!relative.startsWith("..") && !path.isAbsolute(relative))
  );
}

/** True when `file` lies in any of `dirs` (see {@link isInside}). */
export function isInsideAny(file: string, dirs: readonly string[]): boolean {
  return dirs.some((dir) => isInside(file, dir));
}

/**
 * The asset directories worth watching: absolute, de-duplicated, and inside
 * the project directory. An asset outside the project is never linked (the
 * webview's resource roots stop at the project, and so does the preview's
 * resolver), so a change there could not show up anyway.
 */
export function watchedAssetDirs(
  assetDirs: PreviewAssetDirs,
  projectDir: string,
): string[] {
  const root = path.resolve(projectDir);
  const dirs = [assetDirs.generated, assetDirs.external]
    .filter((dir): dir is string => dir !== undefined)
    .map((dir) => path.resolve(dir))
    .filter((dir) => isInside(dir, root));
  return [...new Set(dirs)];
}

/** Characters with a meaning in a VS Code glob pattern. */
const GLOB_SPECIAL = /[*?[\]{}!]/;

/**
 * A glob, relative to `projectDir`, matching everything below `dir`.
 *
 * The watcher is anchored at the project directory rather than at `dir` so
 * that a directory which does not exist yet (the generated directory, before
 * the first `pretext generate`) is still watched, and picked up the moment it
 * is created. A directory name with glob characters in it cannot be spelled
 * as a literal glob, so it falls back to the whole project; the event handler
 * filters by {@link isInsideAny} in any case.
 */
export function assetWatchGlob(projectDir: string, dir: string): string {
  const relative = path
    .relative(path.resolve(projectDir), path.resolve(dir))
    .split(path.sep)
    .join("/");
  if (relative === "" || GLOB_SPECIAL.test(relative)) {
    return "**";
  }
  return `${relative}/**`;
}
